-- F12: cardapio do Iracema (conteudo publico, texto revisado). Nao publica o cardapio (cardapio_publicado segue false).
-- Fonte e lista de correcoes: docs/TEGGLY_DIGITAL_MENU.md e docs/cardapio/iracema-seed.json. Nao reaplicar.
DO $$ DECLARE tid uuid; cid uuid; BEGIN
  SELECT id INTO tid FROM public.tenants WHERE slug='iracema';
  IF tid IS NULL OR EXISTS (SELECT 1 FROM public.cardapio_categorias WHERE tenant_id=tid) THEN RAISE EXCEPTION 'iracema ausente ou cardapio ja tem dados'; END IF;
END $$;
